#include "stdlib/math/base/special/roundnf.h"
#include <stdio.h>

int main( void ) {
	const float x[] = { 3.141592f, -3.141592f, 1234.56f, -1234.56f, 9.99999f, -9.99999f, 0.0f, -0.0f };
	const int32_t n[] = { -2, -2, 2, 2, -2, -2, -2, -2 };

	float v;
	int i;
	for ( i = 0; i < 8; i++ ) {
		v = stdlib_base_roundnf( x[ i ], n[ i ] );
		printf( "roundnf(%f, %d) = %f\n", x[ i ], n[ i ], v );
	}
	return 0;
}
